 function start(){mode='playing';score=0;dust=0;lives=3;lane=0;angle=-Math.PI/2;elapsed=0;spawnTimer=.75;entities=[];particles=[];invuln=1.5;shake=0;last=performance.now();updateHud();$('startOverlay').classList.add('hidden');$('overOverlay').classList.add('hidden');$('pauseOverlay').classList.add('hidden');$('pauseBtn').style.display='grid';$('footer').innerHTML='TAP ANYWHERE TO <strong>FLIP ORBITS</strong>';tone(540,.11,'sine')}
 function finish(){if(mode!=='playing')return;mode='over';$('pauseBtn').style.display='none';best=Math.max(best,score);localStorage.setItem('pocketOrbitBest',best);$('best').textContent=best;$('finalScore').textContent=Math.floor(score);$('finalDust').textContent=dust;$('finalBest').textContent=best;$('overMessage').textContent=score>=best&&score>0?'A new high score! The cosmos knows your name.':'Every orbit has its end. Ready for another?';$('overOverlay').classList.remove('hidden');$('footer').textContent='';tone(170,.35,'triangle',.06)}
